  "Targets stay where you set them.": "目標は設定した値のままです。",
  "Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.": "全セットで目標回数を達成すると重量が増えます。未達成が続くと負荷を軽減します。",
  "Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.": "通常の2セットに加え、最後のセットは限界まで行います。最後のセットで目標回数を超えると重量が増えます（目標の2倍の回数なら増加幅も2倍）。1回でも目標を達成できないと、重量を10％下げます。",
  "Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.": "同じ重量で、設定範囲内の回数を徐々に増やします。全セットで上限回数に達すると重量を増やし、回数を下限に戻します。",
  "Hold every set for the full duration and the target goes up.": "全セットで目標時間まで保持できると、目標時間が延びます。",
  "Nothing logged yet, so this session sets the baseline.": "まだ記録がないため、今回のトレーニングが基準になります。",
  "Held every set for the full time. Target goes up by {0}s.": "全セットで目標時間を達成しました。目標を{0}秒延ばします。",
  "Short {0} sessions in a row. Back off to {1}s and build up again.": "{0}回連続で目標時間に届きませんでした。{1}秒に戻し、再び伸ばしていきましょう。",
  "Came up short last time. Same target again.": "前回は目標に届きませんでした。今回も同じ目標です。",
  "Top of the rep range in every set. {0} {1} more, back to {2} reps.": "全セットで上限回数を達成しました。{0} {1}増やし、{2}回に戻します。",
  "Stuck for {0} sessions. Deload to {1} {2}.": "{0}回のトレーニングで停滞しています。{1} {2}まで負荷を下げます。",
  "Same weight, aim for {0} reps this time.": "重量はそのまま、今回は{0}回を目指しましょう。",
  "Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.": "最後のセットで目標の2倍の{0}回を達成！通常の2倍の幅で、{1} {2}増やします。",
  "Every rep last time. {0} {1} more.": "前回は全セットで目標回数を達成しました。{0} {1}増やします。",
  "Missed reps {0} sessions running. Reset to {1} {2} and work back up.": "{0}回連続で目標回数に届きませんでした。{1} {2}に戻し、再び増やしていきましょう。",
  "Missed reps. Reset to {0} {1} and work back up.": "目標回数に届きませんでした。{0} {1}に戻し、再び増やしていきましょう。",
  "Missed reps last time. Same weight again ({0} of {1} to go).": "前回は目標回数に届きませんでした。今回も同じ重量です（{1}回のうち、あと{0}回）。",
  "Bodyweight: every rep last time, so go for {0} this time.": "自重：前回は全セットで目標回数を達成したので、今回は{0}回を目指しましょう。",
  "Bodyweight: same target again until every set is clean.": "自重：全セットを正しいフォームで達成できるまで、同じ目標を続けます。",
  "{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.": "{0}セットに{1}が含まれています。表示するには、設定で「セットごとのきつさ」をオンにしてください。",
  "{0} sets bring an {1} with them.": "{0}セットに{1}が含まれています。",
  "RIR": "RIR",
  "RPE": "RPE",
  "Effort per set": "セットごとのきつさ",
  "What are RIR and RPE?": "RIRとRPEとは？",
  "How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.": "セットのきつさを、重量や回数と一緒に記録します。同じきつさを、逆方向から数値化する2つの尺度です。",
  "How it felt": "体感",
  "Nothing left, went to failure": "余力なし、限界まで",
  "One more rep in the tank": "あと1回できた",
  "Two more reps": "あと2回できた",
  "Three more reps": "あと3回できた",
  "Easy, warm-up territory": "楽、ウォームアップ程度",
  "RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.": "RIRは「あと何回できたか」、RPEは同じきつさを10段階で表します。関係はRPE ≈ 10 − RIRです。考えやすいほうを選んでください。",
  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "強調した行は、通常のメインセットの目安です。記録済みのセットは元の尺度を保持します。この値はほかの計算には使われないため、負荷の自動調整や推定1RMには影響しません。",
  "Effort": "きつさ",
