  "{0}/side": "片側{0}",
  "{0} reps in every set! Add a set and go back to {1}.": "全セットで{0}回達成！セットを1つ追加して、{1}回に戻しましょう。",
  "{0} sets of {1}. Time to add weight or try a harder variation.": "{1}回を{0}セット達成。重量を増やすか、より難しいバリエーションに挑戦しましょう。",
  "{0} per side": "片側{0}",
