  "Warm-up sets": "ウォームアップセット",
  "Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.": "メインセットの前に追加され、トレーニング量、記録更新、負荷を増やす判断には含まれません。セットごとにメインセットの重量との差を半分ずつ縮めます。バーベル種目ではバー自体の重量を下回りません。トレーニング中でも各セットを変更できます。",
  "Added before your work sets and left out of volume, records and progression. On an assistance machine each one has more help than the work set, stepping down toward it, and you can still change any of them mid-session.": "本番セットの前に追加され、総負荷量、記録、進捗からは除外されます。アシストマシンでは、それぞれ本番セットより補助が大きく、段階的に近づいていきます。トレーニング中でもいつでも変更できます。",
  "Ramp-up sets added before the work sets, so you do not have to add them by hand each session.": "段階的に重量を上げるセットをメインセットの前に追加します。毎回手動で追加する必要はありません。",
