  "Rest-pause always trains as one warm-up set at this rep count, then one rest-pause work set. \"Sets\" isn’t used here.": "レストポーズでは、必ずこの回数でウォームアップを1セット行い、その後にレストポーズのメインセットを1セット行います。「セット数」の設定は使いません。",
