  "The Coach is already thinking about your training.": "コーチはすでにあなたのトレーニングを検討中です。",
  "The Coach is taking a breather. You’ve used today’s {0} runs on this phone.": "コーチはひと休み中です。このスマートフォンでの本日の利用枠{0}回を使い切りました。",
  "The Coach isn’t set up on this phone.": "このスマートフォンではコーチが未設定です。",
