  "The key is stored in this phone’s secure storage and never leaves it except to call the provider.": "キーはこのスマートフォンの安全なストレージに保存され、プロバイダーへの接続時以外は外部に送信されません。",
  "This phone calls the provider directly with your key. Every request is charged to your account.": "このスマートフォンから、あなたのキーでプロバイダーに直接接続します。リクエストごとにあなたのアカウントに課金されます。",
  "Turn the Coach off on this phone": "このスマートフォンのコーチをオフにする",
  "Use my self-hosted openGym": "自分でホストしているopenGymを使う",
