  "Your server has no Coach enabled. Ask its admin, or bring your own key below.": "サーバーでコーチが有効になっていません。管理者に問い合わせるか、以下で自分のキーを設定してください。",
  "Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.": "サーバーは管理者が設定したプロバイダーでコーチを実行します。このスマートフォンから送信されるのは、すでに同期している情報だけです。",
