  "Discarded. Tell me what was off and I will build a different one.": "破棄しました。合わなかった点を教えてください。別のプランを作ります。",
  "Done! Your plan is back to how it was before my last changes.": "完了しました！プランを前回の変更前に戻しました。",
  "Edit my answers": "回答を編集",
  "Experience": "経験",
  "Goal, days, equipment, limits": "目標、日数、器具、制限",
  "Have a look at my training and tell me what you would change.": "トレーニングを見て、改善点を教えてください。",
  "Here is what I am working with:": "私の状況はこちらです：",
  "Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.": "こんにちは、あなたのコーチです。回答をもとにプランを作り、実際の記録に合わせて調整します。あなたの同意なしに変更することはありません。",
  "I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.": "全体を確認しましたが、今は変更の必要がありません。この調子で続けて、あと数回トレーニングしたらまた聞いてください。",
  "I understand, let’s go": "理解しました。始める",
  "Imported! {0} routines are in your plan and your week is set. See you at the next session.": "取り込みました！プランに{0}件のルーティンを追加し、週間スケジュールも設定しました。次のトレーニングでまた会いましょう。",
  "Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.": "取り込みました！プランに{0}件のルーティンを追加しました。週間スケジュールは変更していないので、好きな日に設定してください。",
  "It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.": "いくつかの回答からプランを作り、実際の記録に合わせて調整します。あなたの同意なしに変更することはなく、すべての変更を元に戻せます。",
  "Routines, exercises, sets and reps, your weekly schedule and progression settings.": "ルーティン、種目、セット数と回数、週間スケジュール、負荷の増やし方の設定。",
  "Your logged training": "記録したトレーニング",
  "Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.": "振り返り対象期間のセット記録：重量、回数、タイム、きつさの評価、トレーニングの所要時間、各回のメモ。",
  "Weigh-ins from the same window, and your goal weight if you set one.": "同じ期間の体重記録と、設定している場合は目標体重。",
  "What you tell the Coach": "コーチに伝える情報",
  "Your intake answers, including any limitations or injuries you describe.": "最初の質問への回答。伝えた制限やけがの情報も含まれます。",
  "A few preferences": "いくつかの設定",
