  "Account ID copied": "アカウントIDをコピーしました",
  "Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.": "Androidはアプリからの暗号化されていないhttp://接続をブロックするため、このスマートフォンから接続できるのはhttps://のエンドポイントのみです。TailscaleやリバースプロキシでHTTPS経由にするか、「自分でホストしているopenGymを使う」を選んでください。サーバーからは、同じネットワーク内のhttp://のモデルに接続できます。",
  "Structural balance": "筋力バランス",
  "See which lift is holding back the rest.": "他の種目の伸びを妨げている種目を確認します。",
