  "The server has {0} workouts that are not in this backup, logged since it was made or on another device. Replacing deletes them.": "サーバーには、このバックアップに含まれないトレーニングが{0}件あります。バックアップ作成後、または別の端末で記録されたものです。置き換えると削除されます。",
