  "The Coach couldn’t run. The instance owner needs to check its setup.": "コーチを実行できませんでした。サーバー管理者による設定の確認が必要です。",
  "The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.": "コーチがAIプロバイダーの利用上限に達しました。後でもう一度お試しいただくか、インスタンスの管理者にプランやキーを確認してもらってください。",
  "The Coach’s AI provider rejected the request format. The instance owner needs to try another model.": "コーチのAIプロバイダーがリクエスト形式を拒否しました。インスタンスの管理者が別のモデルを試す必要があります。",
  "The Coach’s AI provider is having an outage. Try again in a little while.": "コーチのAIプロバイダーで障害が発生しています。少し時間をおいてお試しください。",
  "The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.": "コーチがAIプロバイダーに接続できませんでした。インスタンスの管理者がエンドポイントとネットワークを確認する必要があります。",
  "The Coach answered with something the app couldn’t use.": "コーチの回答はアプリで扱えない形式でした。",
