  "Tap a routine to edit it. Reorder and delete are behind Edit.": "ルーティンをタップすると編集できます。並べ替えと削除は「編集」から行えます。",
  "Pick one routine, or more to train them together.": "ルーティンを1つ選んでください。複数選ぶと、まとめてトレーニングできます。",
