  "Add to this set": "このセットに追加",
  "Copy this exercise’s warm-up sets, and the rest and note from its Exercise settings, into the routine. A note added for today stays with this workout. Your workout history is kept.": "この種目のウォームアップセットと、種目設定の休憩・メモをルーティンにコピーします。今日のために追加したメモは、このトレーニングに残ります。トレーニング履歴は保持されます。",
