  "Finish and save": "終了して保存",
  "Make it a warm-up set": "ウォームアップセットにする",
  "Count it as a working set": "メインセットとして数える",
  "That looks too heavy. Keep it at {0} or less.": "重量が大きすぎるようです。{0}以下にしてください。",
  "That’s still in the future. Try an earlier start.": "開始日時がまだ未来になっています。もっと前に設定してください。",
  "That’s more than a day. Keep it to 24 hours or less.": "1日を超えています。24時間以内にしてください。",
  "That file isn’t an openGym backup.": "このファイルはopenGymのバックアップではありません。",
  "That zip was repacked. Import the original backup file.": "このZIPは再圧縮されています。元のバックアップファイルを取り込んでください。",
  "Couldn’t read that file.": "ファイルを読み取れませんでした。",
  "This server doesn’t know that passkey. Make a profile first.": "このパスキーはサーバーに登録されていません。先にプロフィールを作成してください。",
  "That took a little too long. Give it another go.": "時間がかかりすぎました。もう一度お試しください。",
  "This server only takes changes made at {0}. If you opened openGym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).": "このサーバーは{0}からの変更のみ受け付けます。別のアドレスでopenGymを開いた場合は、サーバー管理者がORIGINとRP_IDをそのアドレスに合わせて設定できます（手順はセルフホスティングガイドを参照）。",
  "That code didn’t work. Codes last 5 minutes and work once, so grab a fresh one.": "このコードは使えませんでした。コードの有効期限は5分で、1回限り使えます。新しいコードを取得してください。",
