  "Options: copy, remove": "オプション：コピー、削除",
  "Another device synced while you were importing, so its changes were kept next to the backup.": "取り込み中に別の端末が同期したため、その変更もバックアップの内容とともに保持しました。",
  "Save as a backup file": "バックアップファイルとして保存",
  "Add this device's plan to your profile?": "この端末のプランをプロフィールに追加しますか？",
  "Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "この端末のプラン・メモ・ジム会員証は、ログアウト中に設定されたものです。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末で{0}件のルーティンが作成されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末で{0}件のルーティンが作成されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "This device, before signing in": "この端末（ログイン前）",
  "This device, before the update": "この端末（更新前）",
  "Your own color": "カスタムカラー",
  "Pick your own color": "好きな色を選択",
  "Change your own color": "カスタムカラーを変更",
  "A touch lighter in dark mode, so you can still read it.": "ダークモードでは、読みやすいように少し明るく表示します。",
  "A touch darker in light mode, so you can still read it.": "ライトモードでは、読みやすいように少し暗く表示します。",
  "Greys show lighter in dark mode, so buttons don’t look switched off.": "ダークモードでは、ボタンが無効に見えないようにグレーを明るく表示します。",
  "Greys show darker in light mode, so buttons don’t look switched off.": "ライトモードでは、ボタンが無効に見えないようにグレーを暗く表示します。",
  "custom color picker": "カスタムカラー選択",
  "Signed in from another tab. Your workout came along, keep going here.": "別のタブでログインしました。トレーニングも引き継いだので、ここで続けられます。",
  "Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.": "http:// は暗号化されません。自宅のネットワーク内では使えますが、インターネットからアクセスできるサーバーには https:// を使ってください。",
  "Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.": "https:// で {0} に接続できませんでした。サーバーが暗号化なしの HTTP で動作している場合（自宅ではよくある設定です）は、代わりに http://{0} と入力してください。",
  "Health Connect": "Health Connect",
