  "The last set goes until nothing is left, and counts as all-out effort unless you rate it.": "最終セットは限界まで行います。きつさを自分で評価しない場合は、全力として記録します。",
  "Plan the final set as an all-out one.": "最終セットを全力で行う設定にします。",
  "Triple progression": "3段階プログレッション",
  "Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.": "まず回数を範囲の上限まで増やし、次にセット数を上限まで増やします。全セットで回数の上限に達したら重量を増やし、セット数と回数を開始時の値に戻します。",
  "Same weight, aim for {0} reps in every set.": "重量はそのまま、全セットで{0}回を目指しましょう。",
  "Same weight, aim for {0} reps on the last set.": "重量はそのまま、最終セットで{0}回を目指しましょう。",
  "{0} reps in every set! Add a set at {1} reps.": "全セットで{0}回達成！{1}回のセットを1つ追加しましょう。",
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "全{0}セットで回数の上限に到達。重量を{1} {2}増やし、{4}回×{3}セットに戻します。",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "全{0}セットで回数の上限に到達。補助重量を{1} {2}減らし、{4}回×{3}セットに戻します。",
  "Short of the target, but more reps than before. Same sets and reps again.": "目標には届きませんでしたが、前回より回数が増えました。同じセット数と回数でもう一度。",
  "Missed reps last time. Same sets and reps again ({0} of {1} to go).": "前回は目標回数に届きませんでした。同じセット数と回数でもう一度（{1}回中、残り{0}回）。",
  "Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.": "{0}回のトレーニングで停滞しています。重量を{1} {2}に下げ、{4}回×{3}セットから再開します。",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "{0}回のトレーニングで停滞しています。補助重量を{1} {2}に戻し、{4}回×{3}セットから再開します。",
