  "openGym is on your Apple Watch": "Apple WatchにopenGymがインストールされています",
  "Last heard from the watch: {0}": "ウォッチとの最終通信：{0}",
  "The watch hasn’t checked in yet. Open openGym on it once.": "ウォッチとはまだ通信できていません。ウォッチでopenGymを一度開いてください。",
  "Not allowed on the watch. Allow it in the Health app on your iPhone.": "ウォッチで許可されていません。iPhoneのヘルスケアアプリで許可してください。",
  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "トレーニング中や各セットの横に心拍数を表示し、トレーニングをAppleヘルスケアに保存します。ウォッチで初回のみ許可を求めます。",
  "Apple Health": "Appleヘルスケア",
  "Write to Apple Health": "Appleヘルスケアに書き込む",
  "Open Apple Health": "Appleヘルスケアを開く",
  "Workouts and weigh-ins go to Apple Health when you finish or change them.": "トレーニングや体重測定を終えたとき、または記録を変更したときに、Appleヘルスケアに送信します。",
  "Writing to Apple Health": "Appleヘルスケアに書き込み中",
  "Apple Health permission not granted": "Appleヘルスケアへのアクセスが許可されていません",
  "Could not write to Apple Health": "Appleヘルスケアに保存できませんでした",
  "Could not remove it from Apple Health": "Appleヘルスケアから削除できませんでした",
  "Stop writing to Apple Health?": "Appleヘルスケアへの保存を停止しますか？",
  "What openGym already wrote can stay in Apple Health as your data, or be removed from it.": "openGymが保存済みのデータは、自分のデータとしてAppleヘルスケアに残すことも、削除することもできます。",
  "Your workouts in Apple Health": "トレーニングをAppleヘルスケアに",
  "openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.": "openGymは毎回のトレーニングと体重測定をAppleヘルスケアに保存できます。トレーニング中の心拍数はApple Watchで確認できます。",
  "Workouts and weigh-ins saved to Apple Health": "トレーニングと体重測定をAppleヘルスケアに保存",
  "Heart rate per set on your Apple Watch": "セットごとの心拍数をApple Watchで確認",
  "AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.": "AirPods Pro 3かPowerbeats Pro 2を装着していますか？Apple Watchで測定中でなければ、iPhoneがセットごとの心拍数を測定します。",
  "Switch it off anytime in Settings": "設定からいつでもオフにできます",
