  "On the watch": "ウォッチの表示",
  "Fewer things, bigger numbers. Pick what helps you mid-set.": "表示を絞って、数字を大きく。セット中に必要なものを選べます。",
  "Exercise animation": "種目のアニメーション",
  "Heart rate": "心拍数",
  "Time so far": "経過時間",
