  "One weigh-in": "体重測定1回",
  "No weigh-ins": "体重測定なし",
  "Training time": "トレーニング時間",
  "Arrows compare with the {0} days before.": "矢印は、その前の{0}日間との比較を示します。",
  "Volume per day": "1日あたりの総負荷量",
