  "Your programmes": "自分のプログラム",
  "Your routines as a block of weeks, each week with its own %1RM or RPE.": "自分のルーティンを数週間のプログラムにまとめ、週ごとに%1RMやRPEを設定できます。",
  "Your routines as a block of weeks, with starter programmes to try.": "自分のルーティンを数週間のプログラムにまとめられます。試せる入門プログラムもあります。",
