  "Time per exercise": "種目ごとの時間",
  "Average time a session, counted from when its sets were ticked.": "セットを完了にした時刻をもとに計算した、1回のトレーニングでの平均所要時間です。",
  "No timed sets in this period.": "この期間に時間を記録したセットはありません。",
  "Profile default ({0})": "プロフィールの既定値（{0}）",
  "For gyms that mix kg and lb. This exercise is shown and typed in it everywhere, plates and steps included. Totals in Stats stay in {0}.": "キログラムとポンドが混在するジム向けです。この種目の表示と入力は、プレートや重量の増減幅も含め、すべてこの単位になります。「統計」の合計は引き続き{0}で表示します。",
  "Back to top": "先頭に戻る",
