  "Backups, imports and syncing with your own server.": "バックアップ、インポート、自分のサーバーとの同期。",
  "Body map": "筋肉マップ",
  "Catch your breath": "ひと息つきましょう",
  "Done with a set? Tick it. Go on, try it.": "セットが終わったらチェックを入れましょう。試してみてください。",
  "Filter it down": "絞り込み",
