  "This lives in the openGym phone app.": "この機能はスマートフォン版openGymで使えます。",
  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "お使いの時計や体重計もここにデータを書き込んでいますか？Garmin、COROS、Fitbit、Withings、Ouraなどのデータは、ここを経由してopenGymに届きます。",
  "Now in Integrations": "「連携」に移動しました",
