  "Three goals a month on Home, sized to how you train.": "トレーニングのペースに合った3つの目標を、毎月ホームに表示します。",
  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "暗号化されていないhttp://は、192.168.x.x、.local名、Tailscaleの100.xアドレスなど、ホームネットワーク内のアドレスでのみ使えます。インターネット上の接続先にはhttps://が必要です。",
  "Plain http only on your home network": "暗号化されていないhttpはホームネットワーク内のみ",
  "Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.": "フリースタイルでは負荷の増やし方のルールを使わず、前回と同じ内容を繰り返します。ルールはルーティン内の種目に適用されます。",
  "Your watch thought this workout was forgotten. It keeps going here.": "ウォッチはこのトレーニングを終了し忘れたと判断しました。こちらでは継続しています。",
