  "Body": "自重",
  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "メインセットの重量を基に、このジムのプレートとダンベルで使える重量に調整します。種目の設定で個別に指定することもできます。",
