  "Default (none)": "既定（なし）",
  "Do {0} last": "{0}を最後に行う",
  "Do {0} next": "{0}を次に行う",
  "Each one closes half the gap to the work weight.": "セットごとに、メインセットの重量との差を半分ずつ縮めます。",
  "Every loaded lift": "重量を使うすべての種目",
  "Feeling great": "調子がいい",
  "Follows Settings → Workout → Automatic warm-ups.": "設定 → トレーニング → 自動ウォームアップの設定に従います。",
  "For this workout": "今回のトレーニングのみ",
  "Heavy lifts get more rungs, light ones one or none.": "重量が重い種目では段階を増やし、軽い種目では1段階またはなしにします。",
  "It hurts": "痛みがある",
  "It hurts, it’s taken, no time, feeling great": "痛みがある、器具が使用中、時間がない、調子がいい",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "鋭い痛みがあるため、残りは重量を軽くします。それでも痛む場合は中止してください。",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "鋭い痛みがあるため、残りのセットは同じ筋肉をより無理のない角度で鍛える動きに変更します。",
  "Keep these warm-ups": "このウォームアップを保存",
  "Kept. Same warm-ups next time, scaled to your work weight.": "保存しました。次回も同じウォームアップを、メインセットの重量に合わせて調整します。",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "記録済みのセットとルーティンは変更されません。コーチは医師や理学療法士ではありません。痛みがある場合は専門家に相談してください。",
  "Looking at your workout…": "トレーニングを確認中…",
