  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "1週休んでもフリーズが補ってくれます。連続記録は続き、その週はカウントに加わらないだけです。2週続けて休むと、最初からやり直しです。",
  "No freezes": "フリーズなし",
