  "No freezes on your rule: a week without a workout starts it over.": "このルールにはフリーズがありません。トレーニングのない週があると最初からです。",
  "No workout, and your rule has no freezes, so the streak started over.": "トレーニングがなく、ルールにフリーズもないので、連続記録はリセットされました。",
