  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "このトレーナーに、ここで選んだカテゴリーの閲覧と、「提案」または「適用」にしたカテゴリーの変更を許可します。トレーナーがジムに所属している場合、そのジム責任者はジム責任者の行のカテゴリーだけを見られ、閲覧以上の権限はありません。これはいつでも変更や接続解除ができ、その瞬間に無効になります。閲覧や変更はすべて共有ログに記録され、そのログを読めるのはあなただけです。",
