  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "このファイルには位置情報などの隠れた情報が残っています。アプリでもう一度追加して、新しいコピーを共有してください。",
  "That is not shared any more.": "それはもう共有されていません。",
