  "The sharing text changed. Have a quick read and try again.": "共有の説明文が変わりました。さっと目を通して、もう一度お試しください。",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "これはこのサーバーの全員に公開されます。ここにアカウントを持つ人なら誰でも見て、試して、コピーできます。あなたの名前と日付は必ず一緒に表示されます。共有するのは自分のものだけにしてください。自分で作った・記録した、または共有する権利のあるものです。内蔵ライブラリの種目画像とアニメーションはライセンス品のため、共有できません。共有はいつでもやめられますが、すでにコピーされたものは相手の手元に残ります。",
