  "A one-time download of about {0} from Google Play, over Wi-Fi. It stays on this phone.": "Google PlayからWi-Fi経由で約{0}の1回限りのダウンロードです。この端末に保存されます。",
  "A one-time download from Google Play, over Wi-Fi. It stays on this phone.": "Google PlayからWi-Fi経由の1回限りのダウンロードです。この端末に保存されます。",
