  "Changed your mind? Settings has it, any time.": "気が変わったら、いつでも「設定」から変更できます。",
  "A profile here already uses that e-mail. Sign in to it another way, then link {0} in Settings.": "このメールアドレスはすでに別のプロフィールで使われています。別の方法でそちらにログインしてから、「設定」で{0}を連携してください。",
