  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "このサーバーは招待制で、{0}だけでは参加できません。運営者にお問い合わせください。",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "このサーバーでは全員が{0}でログインします。初めてですか？ログインするとプロフィールが作成されます。",
