  "Too many attempts. Try again in a minute.": "試行回数が多すぎます。1分後にもう一度お試しください。",
  "Unlink": "連携を解除",
  "Unlinked. {0} no longer signs you in here.": "連携を解除しました。{0}ではここにログインできなくなりました。",
  "or use a pairing code": "またはペアリングコードを使う",
  "{0} could not be reached. Try again in a moment.": "{0}に接続できませんでした。少ししてからもう一度お試しください。",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0}はこのプロフィールに入る唯一の方法なので、連携は解除できません。先にパスキーを追加してください。",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0}での認証は通りましたが、このサーバーは特定のグループしか受け付けていません。運営者に追加を依頼してください。",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0}から確認できない応答が返ってきたため、誰もログインしていません。繰り返し起きる場合は、管理ページで原因を確認できます。",
  "Backups: {0}": "代替：{0}",
  "Suggested": "おすすめ",
  "Add “{0}” as a backup": "「{0}」を代替として追加",
  "Ask the Coach for a swap": "コーチに代わりの種目を聞く",
  "Per gym": "ジムごと",
  "Separate numbers per gym": "ジムごとに別々の数値",
  "Last time and the next weight come from this gym only.": "前回の記録と次の重量は、このジムの分だけから決まります。",
  "Brand at {0}": "{0}のメーカー",
  "Life Fitness, Technogym… (optional)": "Life Fitness、Technogymなど（任意）",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "別のジムに同じメーカーがありますか？その場合はこの数値を共有します。記録と統計は引き続きすべてのジムを合算します。",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "ジムによって感覚が違うマシンやケーブル向けです。フリーウェイトにはほとんど不要です。",
  "All gyms": "すべてのジム",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "{0}向けに予定していた今日のメニューが合わなかったので、ルーティン本来のメニューを表示しています：{1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "今日のメニューは{0}からです。ルーティンはそのままです。",
  "Today’s rows were planned for this day. Your routine stays as it is.": "今日のメニューはこの日用に予定されたものです。ルーティンはそのままです。",
  "Body composition from your scale": "体組成計からの体組成",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "体組成計が保存した体脂肪と除脂肪量です。「身体測定」に表示され、ご自身の記録と混ざることはありません。",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "体組成計が保存した体脂肪、除脂肪量、骨量、体水分量、基礎代謝量です。「身体測定」に表示され、ご自身の記録と混ざることはありません。",
  "From Health Connect": "Health Connectから",
  "From Apple Health": "Apple Healthから",
  "Lean mass": "除脂肪量",
  "Bone mass": "骨量",
  "Body water": "体水分量",
  "Basal metabolic rate": "基礎代謝量",
  "{0} in a month": "1か月で{0}",
  "Straight from your scale, read-only. Change it where it was measured.": "体組成計からそのまま取り込んだ読み取り専用のデータです。変更は測定した側で行ってください。",
  "You made the token {0}": "トークン{0}を作成しました",
  "The token {0} was revoked": "トークン{0}が無効化されました",
  "The token {0} changed {1}": "トークン{0}が{1}を変更しました",
  "A token lets one program, like an AI assistant, see or change only what you tick. Never more than you can, and only your own profile.": "トークンを使うと、AIアシスタントなど1つのプログラムに、チェックした内容だけを見せたり変更させたりできます。あなたの権限を超えることはなく、対象はあなた自身のプロフィールだけです。",
  "API token": "APIトークン",
  "API tokens": "APIトークン",
  "Add it as a custom connector in your AI assistant, with a token from below.": "下のトークンを使って、AIアシスタントにカスタムコネクタとして追加してください。",
  "After a year": "1年後",
  "After {0} days": "{0}日後",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "今すぐコピーしてください。openGymが表示するのはこの1回だけです。パスワードと同じように扱ってください。",
  "Ends": "有効期限",
  "Every program using one stops getting in right away.": "これを使っているプログラムは、すぐにアクセスできなくなります。",
  "For AI assistants over MCP, planners and scripts. Each sees only what you tick.": "MCP経由のAIアシスタント、プランナー、スクリプト向けです。それぞれ、チェックした内容だけが見えます。",
  "For example: Claude": "例：Claude",
  "How to connect an assistant:": "アシスタントの接続方法：",
