  "Never used": "未使用",
  "New token": "新しいトークン",
  "No tokens yet. Make one for each program, so you can revoke them one by one.": "まだトークンがありません。プログラムごとに1つ作れば、個別に無効化できます。",
  "Pick at least one thing it may see.": "見せるものを1つ以上選んでください。",
  "Revoke": "無効化",
