  "Revoke all tokens": "すべてのトークンを無効化",
  "Revoke all tokens?": "すべてのトークンを無効化しますか？",
  "See reads. Change directly also writes, over the exact version it read.": "「閲覧」は読み取りのみ。「直接変更」は書き込みもでき、読み取ったときのバージョンに対して書き込みます。",
  "Starts with": "先頭の文字",
