  "Your new token": "新しいトークン",
  "Your tokens": "あなたのトークン",
  "Runs next to your server, or over HTTPS with a token from Settings.": "サーバーと同じ場所で動かすか、「設定」で発行したトークンを使ってHTTPS経由で接続します。",
  "Sees and changes only what the token was given.": "トークンに許可された内容だけを閲覧・変更します。",
  "A guess from the file date. Worth a look.": "ファイルの日付から推測しました。確認しておくと安心です。",
  "Before and after": "ビフォーアフター",
  "Change the day": "日付を変更",
