  "Compare {0} photo": "{0}枚の写真を比較",
  "Compare {0} photos": "{0}枚の写真を比較",
  "Last photo: {0} day ago. Same spot, same light?": "最後の写真：{0}日前。同じ場所、同じ光で撮りますか？",
  "Last photo: {0} days ago. Same spot, same light?": "最後の写真：{0}日前。同じ場所、同じ光で撮りますか？",
  "A buzz for each phase": "フェーズごとに振動",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "すべてのデータを1日1回、自分専用のフォルダにコピーします。Nextcloud、ownCloud、NASなど、WebDAVに対応していれば何でもOK。あなたのサーバーで、ほかの誰のものでもありません。",
  "A sound for each kind of rest": "休憩の種類ごとにサウンド",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "トレーニングした日に、セット数と一緒にチェックが付きます。プランと同じく、見えるのはあなただけです。",
  "A tone for each phase": "フェーズごとに音",
  "Again": "もう一度",
  "An app password is best": "アプリパスワードがおすすめです",
  "Back up every day": "毎日バックアップ",
