  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "このバージョンのopenGymにはGarmin連携がありません。Garmin側の部分がオープンソースではないためです。App Store、Google Play、GitHub版には搭載されています。",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "このスマホにGarmin Connectが入っていません。インストールしてウォッチをペアリングしてから、ここに戻ってきてください。",
  "Garmin Connect needs an update before openGym can talk to your watch.": "openGymがウォッチと通信するには、Garmin Connectのアップデートが必要です。",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Garmin Connectに接続できませんでした。少ししてからもう一度お試しください。",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Garmin ConnectでGarminを選ぶと、トレーニングが手首に表示されます。",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connectにまだウォッチが登録されていません。先にそちらでペアリングしてください。",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "GarminにopenGymが入っています。手首で記録したセットはここに届きます。",
