  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "統計の「毎日のコンディション」カードとチェックイン用。このスマホでだけ読み取り、どこにも送信しません。",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "睡眠、エネルギー、筋肉痛、ストレスを4タップで。調子が悪い日はopenGymが軽めのメニューを提案し、数週間後には調子の良い日の共通点が見えてきます。",
  "Frazzled": "疲れ切っている",
