  "openGym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGymはApple Healthに睡眠、安静時心拍数、心拍変動、歩数の読み取りを求めます。許可したいものだけ選んでください。データはこのスマホのopenGym専用ファイルに保存され、サーバーには送信されません。",
