  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "しかもずっとそのまま：openGym Offlineにはインターネットの権限がないので、何か通信しようとしてもAndroidがブロックします。",
  "Any of the sounds on your phone.": "スマホにあるどのサウンドでも。",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "設定の「データとバックアップ」で、ときどきバックアップしてください。スマホ内のファイルが唯一のコピーです。",
  "Closing the app resets the count; the log never leaves the phone.": "アプリを閉じるとカウントはリセットされます。ログがスマホの外に出ることはありません。",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "アプリが起動した{0}からカウントしています。アプリを閉じるとリセットされます。ログがスマホの外に出ることはありません。",
  "Each reminder can sound different, so you know which one it is before you look.": "リマインダーごとに違う音を設定できるので、見る前にどれか分かります。",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "このアプリがインターネットにリクエストしたすべての通信を、新しい順に。表示するのはアドレスだけで、中身は表示しません。",
  "For reading mid-set without your glasses.": "セット中にメガネなしで読めるように。",
  "Larger": "大きめ",
  "Last at {0}": "最終：{0}",
  "Latest": "最新",
  "Less: no sliding, bouncing or snow. Things just appear.": "控えめ：スライドもバウンドも雪もなし。パッと表示されます。",
  "Like the phone": "スマホと同じ",
  "Mostly your own server, {0}, when there was something to sync.": "同期するものがあったときの、主に自分のサーバー（{0}）。",
  "Motion": "モーション",
  "Network log": "ネットワークログ",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "openGym Offlineでは地図検索ができません。ジムで「現在地」をタップすれば完了です。",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "1バイトたりともこのスマホから出ていません。あなたのトレーニングは、あなただけのものです。",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "まだありません。同期するものがあると、このスマホからサーバーに通信します。",
  "Phone default": "スマホの標準",
  "Phone sound": "スマホのサウンド",
  "Pick a phone sound…": "スマホのサウンドを選ぶ…",
  "Showing the last {0}. The count above has them all.": "直近{0}件を表示中。上のカウントにはすべて含まれています。",
  "Shows up, keeps quiet.": "表示はするけど、音は鳴らさない。",
  "Tap one to hear it. It rings even with the app closed.": "タップで試聴。アプリを閉じていても鳴ります。",
  "Text size": "文字サイズ",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "これはopenGym Offlineです。Androidがインターネットへの接続すら許可しません。同期したいですか？通常のopenGymアプリなら、これと並べて使えます。",
  "Weigh-ins, measurements and progress photos.": "体重測定、測定値、進捗写真。",
  "Whatever your phone uses for notifications.": "スマホが通知に使っているサウンド。",
  "When you walk into your gym.": "ジムに着いたとき。",
  "Who": "通信先",
  "Who this app talked to since you opened it.": "アプリを開いてから、このアプリが通信した相手。",
  "Workout days and the nudge when one slips by.": "トレーニング日と、予定を逃したときのお知らせ。",
  "Workout reminders": "トレーニングのリマインダー",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "openGym Offlineにはインターネットの権限がありません。トレーニングデータはこのスマホの中だけ。以上です。",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offlineはアップデートを確認しません。できないのです。新しいバージョンは、このアプリを入手した場所から手に入ります。",
  "openGym Offline, no internet permission": "openGym Offline、インターネット権限なし",
  "openGym Offline: on this phone, and only here": "openGym Offline：このスマホの中だけ",
