  "This backup belongs to another account": "このバックアップは別のアカウントのものです",
  "Someone else set it up on this device, so nothing of yours goes to their folder. Disconnect it to set up your own.": "この端末では別の人が設定しているので、あなたのデータがその人のフォルダに送られることはありません。自分用に設定するには接続を解除してください。",
  "Routine from a past workout": "過去のトレーニングからルーティン",
  "From a past workout": "過去のトレーニングから",
  "Pick one you did, imported ones too. Its exercises and sets become a routine you can tweak.": "取り込んだものも含めて、実施したトレーニングを選んでください。その種目とセットが、調整できるルーティンになります。",
  "That workout has no exercises to copy.": "そのトレーニングにはコピーする種目がありません。",
  "Saved as a routine. Your workout stays as it was.": "ルーティンとして保存しました。元のトレーニングはそのままです。",
  "Nothing logged yet. Train once, or import your history, and it shows up here.": "まだ記録がありません。一度トレーニングするか履歴をインポートすると、ここに表示されます。",
  "Smallest": "最小",
  "Largest": "最大",
  "Follows your phone’s text size, now {0}.": "スマホの文字サイズ（現在{0}）に合わせます。",
