  "forgotten workout auto finish": "忘れたトレーニング 自動終了 forgotten workout auto finish",
  "Ask “Still training?”": "「まだトレーニング中？」と確認",
  "End by itself when I leave the gym": "ジムを出たら自動で終了",
  "Time to answer": "回答までの時間",
  "Finish the workout you’re on first, then reopen this one.": "先に今のトレーニングを終了してから、こちらを開き直してください。",
