  "Reopen workout": "トレーニングを再開",
  "Still training?": "まだトレーニング中ですか？",
  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "{0}分間セットがありません。終わったのなら、{1}分後に最後のセットの時点で終了します。",
  "Looks like you left the gym": "ジムを出たようです",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "今すぐトレーニングを終了しますか？そうしなければ{0}分後に自動で終了します。",
  "Keep going": "続ける",
  "Finish now": "今すぐ終了",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "今すぐトレーニングを終了しますか？そうしなければ{0}に自動で終了します。",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "しばらく記録がありません。終わったのなら、{0}に自動で終了し、最後のセットの時点で保存します。",
  "Forgotten workouts": "忘れたトレーニング",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "誰も答えなくても自動で終了し、何も消えません。終了時刻は最後のセットとその休憩の後なので、時間は正確なままです。1日以内なら履歴から再開できます。ウォッチでも確認されます。",
  "Never asks and never ends one by itself.": "確認もせず、自動で終了もしません。",
  "The default. Long enough for a chat at the water fountain.": "標準。給水機の前でおしゃべりするのに十分な長さです。",
  "Asks the moment your phone walks out of your gym, then wraps up.": "スマホがジムを出た瞬間に確認して、トレーニングを締めくくります。",
